target.css:
:root {
  --ink: #20243a;
  --muted: #737b97;
  --surface: #ffffff;
  --line: #e2e5f0;
  --lavender: #f0edff;
  --purple: #6857d9;
  --purple-dark: #4939ae;
  --mint: #dff7eb;
  --green: #218e67;
  --coral: #fff0ec;
  --orange: #d96945;
}

.run-card {
  box-sizing: border-box;
  width: 500px;
  padding: 13px 14px 12px;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.run-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.title-block {
  min-width: 0;
}

.eyebrow,
.run-id,
.panel-label,
.note {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.25;
}

.eyebrow {
  margin-bottom: 2px;
  color: var(--purple);
  font-size: 9px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 0;
  letter-spacing: -0.03em;
}

h1 {
  font-size: 20px;
  line-height: 1.05;
}

.run-id {
  margin-top: 3px;
}

.status-badge {
  flex: 0 0 auto;
  padding: 5px 8px;
  color: var(--green);
  background: var(--mint);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin-bottom: 10px;
}

.metric-card {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 9px;
  background: var(--lavender);
  border-radius: 9px;
}

.alert-card {
  background: var(--coral);
}

.metric-label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.metric-card strong {
  font-size: 18px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.metric-card em {
  font-size: 10px;
  font-style: normal;
  letter-spacing: 0;
}

.metric-card small {
  color: var(--muted);
  font-size: 9px;
  line-height: 1.15;
}

.workspace {
  display: grid;
  grid-template-columns: 1.4fr 0.9fr;
  gap: 10px;
  margin-bottom: 10px;
}

.progress-panel,
.sample-panel {
  box-sizing: border-box;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 11px;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
  font-size: 11px;
  font-weight: 750;
}

.panel-header strong {
  color: var(--purple);
}

.progress-track {
  display: block;
  height: 6px;
  overflow: hidden;
  background: var(--lavender);
  border-radius: 999px;
}

.progress-track span {
  display: block;
  width: 64%;
  height: 100%;
  background: var(--purple);
  border-radius: inherit;
}

.phase-list {
  display: grid;
  gap: 4px;
  padding: 0;
  margin: 8px 0 0;
  list-style: none;
}

.phase-list li {
  display: grid;
  grid-template-columns: 16px 1fr auto;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
}

.phase-list b {
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
  box-sizing: border-box;
  border: 1px solid var(--line);
  border-radius: 50%;
  font-size: 9px;
}

.phase-list time {
  font-size: 9px;
}

.complete {
  color: var(--green) !important;
}

.complete b {
  color: var(--surface);
  background: var(--green);
  border-color: var(--green);
}

.active {
  color: var(--ink) !important;
}

.active b {
  color: var(--surface);
  background: var(--purple);
  border-color: var(--purple);
}

.sample-panel {
  display: flex;
  flex-direction: column;
  justify-content: center;
  background: var(--surface);
}

.panel-label {
  margin-bottom: 2px;
  font-size: 9px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

h2 {
  font-size: 14px;
  line-height: 1.2;
}

h2 span {
  color: var(--purple);
  font-size: 10px;
}

.chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 7px 0;
}

.chip-row span {
  padding: 3px 5px;
  color: var(--purple-dark);
  background: var(--lavender);
  border-radius: 4px;
  font-size: 9px;
  font-weight: 750;
}

.note {
  font-size: 9px;
}

.run-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-top: 9px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
}

.run-footer strong {
  color: var(--ink);
}

.action-group {
  display: flex;
  gap: 6px;
}

button {
  padding: 6px 8px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 750;
  line-height: 1;
}

.quiet-button {
  color: var(--purple-dark);
  background: var(--surface);
  border: 1px solid var(--line);
}

.primary-button {
  color: var(--surface);
  background: var(--purple);
  border: 1px solid var(--purple);
}

